-- M9 contract DDL v1. Cross-owner UUIDs are references, never foreign keys.
SET LOCAL timezone = 'UTC';
CREATE TABLE notify_audit.notifications (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), recipient_id uuid NOT NULL, ticket_id uuid, attempt_id uuid, source_event_id uuid NOT NULL, template_version integer NOT NULL CHECK(template_version>0), title text NOT NULL, read_at timestamptz, stored_at timestamptz NOT NULL, UNIQUE(source_event_id,recipient_id));
GRANT SELECT, INSERT, UPDATE ON notify_audit.notifications TO helpdesk_m9;
CREATE TABLE notify_audit.delivery_jobs (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), notification_id uuid NOT NULL REFERENCES notify_audit.notifications(id), channel text NOT NULL CHECK(channel='SINK'), state text NOT NULL CHECK(state IN ('PENDING','LEASED','ACKED','DEAD_LETTER')), attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0), lease_until timestamptz, error_code text);
GRANT SELECT, INSERT, UPDATE ON notify_audit.delivery_jobs TO helpdesk_m9;
CREATE TABLE notify_audit.telegram_bindings (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), subject_id uuid NOT NULL, org_id uuid NOT NULL, chat_ref text NOT NULL, verified_at timestamptz NOT NULL, revoked_at timestamptz, channel text NOT NULL CHECK(channel='SINK'));
GRANT SELECT, INSERT, UPDATE ON notify_audit.telegram_bindings TO helpdesk_m9;
CREATE TABLE notify_audit.audit_entries (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), source_event_id uuid NOT NULL UNIQUE, actor_id uuid NOT NULL, action text NOT NULL, object_id uuid NOT NULL, scope text NOT NULL, reason text NOT NULL, outcome text NOT NULL CHECK(outcome IN ('SUCCESS','DENIED','FAILED')), correlation_id uuid NOT NULL);
GRANT SELECT, INSERT ON notify_audit.audit_entries TO helpdesk_m9;
CREATE TABLE notify_audit.report_facts (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), ticket_id uuid NOT NULL UNIQUE, requester_id uuid NOT NULL, source_version bigint NOT NULL CHECK(source_version>0), org_id uuid NOT NULL, accepted_at timestamptz NOT NULL, resolved_at timestamptz, state text NOT NULL, policy_version integer NOT NULL CHECK(policy_version>0));
GRANT SELECT, INSERT, UPDATE ON notify_audit.report_facts TO helpdesk_m9;
CREATE TABLE notify_audit.export_jobs (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), principal_id uuid NOT NULL, scope_org_ids uuid[] NOT NULL, filter_snapshot jsonb NOT NULL, state text NOT NULL CHECK(state IN ('PENDING','RUNNING','SUCCEEDED','FAILED')), expires_at timestamptz NOT NULL, storage_key text);
GRANT SELECT, INSERT, UPDATE ON notify_audit.export_jobs TO helpdesk_m9;
CREATE TABLE notify_audit.visitor_aggregates (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), period_start timestamptz NOT NULL, period_end timestamptz NOT NULL, bot_policy_version integer NOT NULL CHECK(bot_policy_version>0), session_count bigint NOT NULL CHECK(session_count>=0), CHECK(period_end>period_start));
GRANT SELECT, INSERT, UPDATE ON notify_audit.visitor_aggregates TO helpdesk_m9;
CREATE TABLE notify_audit.idempotency_records (actor_scope text NOT NULL, command text NOT NULL, target text NOT NULL, key text NOT NULL CHECK(length(key) BETWEEN 16 AND 128), payload_digest bytea NOT NULL CHECK(octet_length(payload_digest)=32), response_status integer NOT NULL CHECK(response_status BETWEEN 200 AND 299), response_body jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, PRIMARY KEY(actor_scope,command,target,key));
CREATE TABLE notify_audit.outbox (event_id uuid PRIMARY KEY, event_type text NOT NULL, schema_version integer NOT NULL CHECK(schema_version>0), aggregate_id uuid NOT NULL, aggregate_version bigint NOT NULL CHECK(aggregate_version>0), occurred_at timestamptz NOT NULL, correlation_id uuid NOT NULL, payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'), digest bytea NOT NULL CHECK(octet_length(digest)=32));
CREATE TABLE notify_audit.outbox_delivery (event_id uuid NOT NULL REFERENCES notify_audit.outbox(event_id), consumer_id text NOT NULL CHECK(consumer_id ~ '^M[1-9]$'), state text NOT NULL CHECK(state IN ('PENDING','LEASED','ACKED','DEAD_LETTER')), attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0), lease_until timestamptz, acked_at timestamptz, last_error_code text, PRIMARY KEY(event_id,consumer_id), CHECK((state='ACKED')=(acked_at IS NOT NULL)));
CREATE TABLE notify_audit.inbox (consumer_id text NOT NULL, event_id uuid NOT NULL, digest bytea NOT NULL CHECK(octet_length(digest)=32), aggregate_id uuid NOT NULL, aggregate_version bigint NOT NULL CHECK(aggregate_version>0), received_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(consumer_id,event_id));
CREATE TABLE notify_audit.audit_intents (id uuid PRIMARY KEY, actor_id uuid NOT NULL, action text NOT NULL, object_id uuid NOT NULL, scope text NOT NULL, reason text NOT NULL, outcome text NOT NULL, correlation_id uuid NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON notify_audit.idempotency_records, notify_audit.outbox, notify_audit.inbox, notify_audit.audit_intents TO helpdesk_m9;
GRANT SELECT, INSERT, UPDATE ON notify_audit.outbox_delivery TO helpdesk_m9;
CREATE INDEX ON notify_audit.outbox_delivery (state, lease_until, event_id) WHERE state<>'ACKED';
CREATE INDEX ON notify_audit.notifications (recipient_id,created_at DESC,id DESC);
CREATE INDEX ON notify_audit.report_facts (org_id,accepted_at,id);
REVOKE ALL ON ALL TABLES IN SCHEMA notify_audit FROM PUBLIC;
